// E · Cockpit — pure model (no DOM). Everything numeric here is computed from the stored series or from the API
// answer; the only literals are the declared test presets and assumed-limit defaults, each shown on screen as such.
// Source of truth: this .ts file. cockpit-model.js is generated by `npm --prefix web run build:ts`.
import { DEFAULT_RULES } from "../core/state.js";
import type { Rules } from "../core/state.js";
import { sealFor } from "../core/data.js";
import type { ApiResult, Seal } from "../core/data.js";

/** Declared electrical profile of the lander (hypothetical; every output derived from it is SIM). */
export interface Power { battery_capacity_wh: number; initial_charge_wh: number; solar_generation_w: number; load_w: number; reserve_wh?: number; }
/** One hourly visibility sample. */
export interface Sample { sun_visible: boolean; earth_visible: boolean; }
export interface Fault { id: string; key: string; n?: number; solarFactor?: number; capacityFactor?: number; delayH?: number; noEarth?: boolean; }
export interface ExtraLimits { days: number; sunrises: number; }
export type ApiCall = <T = unknown>(path: string, init?: { method?: string; body?: unknown }) => Promise<ApiResult<T>>;
interface OnboardOption { timeline?: { charge_wh: number }[]; }
interface OnboardResult { science_status?: string; inputs_sha256?: string; options?: OnboardOption[]; }
interface SiteEvaluateResponse { onboard?: OnboardResult; }
export type RunResult =
  | { ok: true; route: "site" | "eval"; trace: number[]; status: string | undefined; option: OnboardOption | undefined; sha: string | undefined }
  | { ok: false; offline: boolean; route: "none"; error: string | undefined };
export interface LightMetrics { longestDarkH?: number | null; longestBlackoutH?: number | null; sunrises?: number | null; }
export interface RuleResult { id: string; status: "pass" | "risk" | "nodata"; seal: Seal; limit: number | null; measured: number | null; source: string; }

export const HOUR_MS = 3600 * 1000;
/** "Testar um problema": the effect of each preset on the declared inputs (shown in the Proof layer). */
export const FAULTS: Readonly<Record<"panel" | "battery" | "delay" | "antenna", Readonly<Fault>>> = Object.freeze({
  panel: Object.freeze({ id: "panel", solarFactor: 0.5, key: "cockpit.problem_panel", n: 50 }),
  battery: Object.freeze({ id: "battery", capacityFactor: 0.8, key: "cockpit.problem_battery", n: 20 }),
  delay: Object.freeze({ id: "delay", delayH: 24, key: "cockpit.problem_delay", n: 24 }),
  antenna: Object.freeze({ id: "antenna", noEarth: true, key: "cockpit.problem_no_antenna" }),
});
/** Declared hypothetical H1 profile. Hypothetical: every output derived from it is SIM. */
export const H1_PROFILE: Readonly<Power> = Object.freeze({ battery_capacity_wh: 20000, initial_charge_wh: 18000, solar_generation_w: 1500, load_w: 600 });
/** Assumed limits that are not in core/state.js DEFAULT_RULES (editable defaults, labelled "assumed limit"). */
export const EXTRA_LIMITS: Readonly<ExtraLimits> = Object.freeze({ days: 5, sunrises: 2 });
export const SPEEDS: readonly number[] = Object.freeze([1, 6, 24]);

/** Apply one fault (or none) to the declared inputs and the visibility samples. Pure. */
export function applyFault(faultId: string | null | undefined, { power, samples, delayH = 0 }: { power: Power; samples: Sample[]; delayH?: number }): { power: Power; samples: Sample[]; delayH: number; fault: Readonly<Fault> | null } {
  const f = (FAULTS as Readonly<Record<string, Readonly<Fault>>>)[faultId as string] || null;
  const p = { ...power };
  let s = samples.map(x => ({ ...x })), d = delayH;
  if (f?.solarFactor) p.solar_generation_w = power.solar_generation_w * f.solarFactor;
  if (f?.capacityFactor) { p.battery_capacity_wh = power.battery_capacity_wh * f.capacityFactor; p.initial_charge_wh = Math.min(power.initial_charge_wh, p.battery_capacity_wh); }
  if (f?.noEarth) s = s.map(x => ({ ...x, earth_visible: false }));
  if (f?.delayH) d += f.delayH;
  return { power: p, samples: s, delayH: d, fault: f };
}

/** Request for POST /api/onboard/site-evaluate (grid-aligned, stored series on the server). */
export function siteEvaluateBody({ siteId, startIso, hours, power, maxBlackoutH, delayH = 0 }: { siteId: string; startIso: string | null; hours: number; power: Power; maxBlackoutH: number; delayH?: number }) {
  return { mission_id: "moonproof-cockpit", start_utc: startIso, duration_hours: hours, max_comm_blackout_hours: maxBlackoutH,
    candidates: [{ id: "cockpit", site_id: siteId, delay_hours: delayH }], power };
}
/** Request for POST /api/onboard/evaluate with visibility booleans taken from the browser's stored series. */
export function evaluateBody({ siteId, startIso, power, maxBlackoutH, samples }: { siteId: string; startIso: string | null; power: Power; maxBlackoutH: number; samples: Sample[] }) {
  return { mission_id: "moonproof-cockpit", candidates: [{ id: "cockpit", site_id: siteId, start_utc: startIso, step_minutes: 60,
    max_comm_blackout_hours: maxBlackoutH, power, samples: samples.map(x => ({ sun_visible: !!x.sun_visible, earth_visible: !!x.earth_visible })) }] };
}

/** Charge trace [Wh] by hour, index 0 = initial charge, from the API's timeline. null when there is none. */
export function chargeTrace(optionLike: OnboardOption | null | undefined, initialWh: number): number[] | null {
  const tl = optionLike?.timeline;
  if (!Array.isArray(tl) || !tl.length || !Number.isFinite(initialWh)) return null;
  const out = [initialWh];
  for (const s of tl) { if (!Number.isFinite(s.charge_wh)) return null; out.push(s.charge_wh); }
  return out;
}

/**
 * Runs the scenario against the API. `call(path, {method, body})` is core/data.js api().
 * 1) POST /api/onboard/site-evaluate (the API's stored series); 2) if that site has none there, POST /api/onboard/evaluate
 * with the booleans of the browser's stored series. Never invents a charge: no answer → {ok:false}.
 */
export async function runScenario(call: ApiCall, { siteId, startIso, hours, power, maxBlackoutH, samples, delayH }: { siteId: string; startIso: string | null; hours: number; power: Power; maxBlackoutH: number; samples: Sample[]; delayH?: number }): Promise<RunResult> {
  const a = await call<SiteEvaluateResponse | null>("/api/onboard/site-evaluate", { method: "POST", body: siteEvaluateBody({ siteId, startIso, hours, power, maxBlackoutH, delayH }) });
  if (a.ok) { const opt = a.data?.onboard?.options?.[0]; const tr = chargeTrace(opt, power.initial_charge_wh);
    if (tr) return { ok: true, route: "site", trace: tr, status: a.data?.onboard?.science_status, option: opt, sha: a.data?.onboard?.inputs_sha256 }; }
  if (a.offline) return { ok: false, offline: true, route: "none", error: a.error };
  const b = await call<OnboardResult | null>("/api/onboard/evaluate", { method: "POST", body: evaluateBody({ siteId, startIso, power, maxBlackoutH, samples }) });
  if (b.ok) { const opt = b.data?.options?.[0]; const tr = chargeTrace(opt, power.initial_charge_wh);
    if (tr) return { ok: true, route: "eval", trace: tr, status: b.data?.science_status, option: opt, sha: b.data?.inputs_sha256 }; }
  return { ok: false, offline: !!b.offline, route: "none", error: b.error || a.error };
}

/** Hours [h] from index i until the Sun/Earth visibility changes, and how long the next opposite state lasts. */
export function nextChange(margin: ArrayLike<number>, i: number, count: number): { visible: boolean; inHours: number | null; lastsHours: number | null } | null {
  if (i < 0 || i >= count) return null;
  const vis = margin[i] >= 0; let k = i + 1;
  while (k < count && (margin[k] >= 0) === vis) k++;
  if (k >= count) return { visible: vis, inHours: null, lastsHours: null };
  let e = k; while (e < count && (margin[e] >= 0) !== vis) e++;
  return { visible: vis, inHours: k - i, lastsHours: e >= count ? null : e - k };
}
/** Number of sunrises (dark → lit) in margin[i0, i0+hours). */
export function countSunrises(margin: ArrayLike<number>, i0: number, hours: number): number {
  let n = 0; for (let i = i0 + 1; i < i0 + hours && i < margin.length; i++) if (margin[i] >= 0 && margin[i - 1] < 0) n++; return n;
}
/** Sunlit fraction per day in [i0, i0+hours); null when the day has no stored sample. */
export function dailyFractions(margin: ArrayLike<number>, i0: number, hours: number): (number | null)[] {
  const out: (number | null)[] = [];
  for (let d = 0; d * 24 < hours; d++) { let on = 0, n = 0;
    for (let h = d * 24; h < Math.min(hours, d * 24 + 24); h++) { const i = i0 + h; if (i < 0 || i >= margin.length) continue; n++; if (margin[i] >= 0) on++; }
    out.push(n ? on / n : null); }
  return out;
}
/** Hours of autonomy at constant load from `chargeWh` down to the floor. null without inputs. */
export function autonomyHours(chargeWh: number, floorWh: number, loadW: number): number | null {
  if (![chargeWh, floorWh, loadW].every(Number.isFinite) || loadW <= 0) return null;
  return Math.max(0, (chargeWh - floorWh) / loadW);
}
/** {d,h} from hours, or null. */
export function splitDuration(h: number): { d: number; h: number } | null { if (!Number.isFinite(h) || h < 0) return null; return { d: Math.floor(h / 24), h: Math.round(h % 24) }; }
export function fmtDuration(h: number, nd = "—"): string { const s = splitDuration(h); if (!s) return nd; return s.d ? `${s.d} d ${s.h} h` : `${s.h} h`; }
/** Slider label "D02 15:48" from the hour offset and the window start (UTC). */
export function clockLabel(startMs: number, h: number): { day: number; hhmm: string; text: string } {
  const d = new Date(startMs + h * HOUR_MS), p = (n: number) => String(n).padStart(2, "0");
  return { day: Math.floor(h / 24) + 1, hhmm: `${p(d.getUTCHours())}:${p(d.getUTCMinutes())}`, text: `D${p(Math.floor(h / 24) + 1)} ${p(d.getUTCHours())}:${p(d.getUTCMinutes())}` };
}

/**
 * The six mission rules. Each → {id, status: "pass"|"risk"|"nodata", seal, measured, limit, source}.
 * Missing input → "nodata" (never "pass"). Limits are the user's assumed limits.
 */
export function evaluateRules({ rules = DEFAULT_RULES, extra = EXTRA_LIMITS, lightStatus, trace, capacityWh, light }: { rules?: Rules; extra?: ExtraLimits; lightStatus?: string | null; trace?: number[] | null; capacityWh?: number | null; light?: LightMetrics | null }): RuleResult[] {
  const lightSeal = sealFor(lightStatus), simSeal = "SIM";
  const out: RuleResult[] = [];
  const floorWh = typeof capacityWh === "number" && Number.isFinite(capacityWh) ? capacityWh * rules.battery / 100 : null;
  const minCharge = trace ? Math.min(...trace) : null;
  out.push({ id: "floor", seal: simSeal, limit: rules.battery, measured: minCharge != null && capacityWh ? 100 * minCharge / capacityWh : null,
    status: minCharge == null || floorWh == null ? "nodata" : minCharge >= floorWh ? "pass" : "risk", source: "API charge trace" });
  out.push({ id: "night", seal: lightSeal, limit: rules.night, measured: light?.longestDarkH ?? null,
    status: light?.longestDarkH == null ? "nodata" : light.longestDarkH <= rules.night ? "pass" : "risk", source: "stored series" });
  out.push({ id: "blackout", seal: lightSeal, limit: rules.blackout, measured: light?.longestBlackoutH ?? null,
    status: light?.longestBlackoutH == null ? "nodata" : light.longestBlackoutH <= rules.blackout ? "pass" : "risk", source: "stored series" });
  // Operation days = hours until the battery is empty (power loss) or the whole window, over 24. Needs the API trace.
  let days = null;
  if (trace) { const first = trace.findIndex(c => c <= 0); days = (first < 0 ? trace.length - 1 : first) / 24; }
  out.push({ id: "days", seal: simSeal, limit: extra.days, measured: days, status: days == null ? "nodata" : days >= extra.days ? "pass" : "risk", source: "API charge trace" });
  out.push({ id: "sunrises", seal: lightSeal, limit: extra.sunrises, measured: light?.sunrises ?? null,
    status: light?.sunrises == null ? "nodata" : light.sunrises >= extra.sunrises ? "pass" : "risk", source: "stored series" });
  out.push({ id: "cold", seal: "N/D", limit: null, measured: null, status: "nodata", source: "no source" });
  return out;
}
export function rulesMet(list: readonly { status: string }[]): { ok: number; of: number } { return { ok: list.filter(r => r.status === "pass").length, of: list.length }; }

/** Longest run of samples where `key` equals `want` (hours at a 1 h step). */
export function longestRun(samples: readonly Record<string, unknown>[], key: string, want: boolean): number {
  let best = 0, cur = 0; for (const x of samples) { if (!!x[key] === want) { cur++; if (cur > best) best = cur; } else cur = 0; } return best;
}
export function countRises(samples: readonly { sun_visible?: unknown }[]): number { let n = 0; for (let i = 1; i < samples.length; i++) if (samples[i].sun_visible && !samples[i - 1].sun_visible) n++; return n; }

/** Simulation clock → whole hour inside [0, hours]. Series and the API charge trace are hourly; never a fraction. */
export function hourIndex(t: number, hours: number): number { return Number.isFinite(t) ? Math.max(0, Math.min(hours, Math.floor(t + 1e-9))) : 0; }
